 for(var x=-10;x<=10;x++)for(var y=0;y<=14;y++){
  var d=x*x+y*y;
  if(d<=r*r+2){
   var s=Math.sqrt(d);
   if(s<1)sb(x,y+baseY+4,z,'iron_block');
   else if(d>r*r-.5)sb(x,y+baseY+4,z,'black_wool');
   else sb(x,y+baseY+4,z,(x*x+y*y)%7===0?'iron_block':'black_wool');
