// === WHEELS (exact MineBench helper pattern) ===
// For upright detection: disc in y-z plane, thickness along x.
// Helper FWD="z": block(cx+t, cy+b, cz+a) -> disc in z-y plane, thick in x
function wheel(cx,cy,cz,r,th,type){
 for(var a=-r;a<=r;a++)for(var b=-r;b<=r;b++){
  var d=a*a+b*b;
  if(d>r*r+r)continue;
  if(r>=5&&d<(r-2)*(r-2)&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
  for(var t=0;t<th;t++)block(cx+t,cy+b,cz+a,type);
 }
}
// Call: cx=center x, cy=center y, cz=center z, r=radius, th=thickness
